(7139598, 1093867, 76335, '<td valign="top">Suggestive framing. Nice.</td>', 'Suggestive framing. Nice.', '2013-12-06 11:06:42.000000', NULL, 1),
(7139599, 1093685, 76335, '<td valign="top">Great title. Remarkably similar to a picture I shot on film a few years ago. Is this New York City?</td>', 'Great title. Remarkably similar to a picture I shot on film a few years ago. Is this New York City?', '2013-12-06 11:08:15.000000', NULL, 1),
(7139600, 1093873, 76335, '<td valign="top">I''m always a bit distracted with both eyes aren''t in focus, but otherwise it''s a good if casual portrait. Looks like available light?</td>', 'I''m always a bit distracted with both eyes aren''t in focus, but otherwise it''s a good if casual portrait. Looks like available light?', '2013-12-06 11:09:13.000000', NULL, 1),
