(7139602, 1093855, 76335, '<td valign="top">Silly title, beautiful image.</td>', 'Silly title, beautiful image.', '2013-12-06 11:12:42.000000', NULL, 1),
(7139603, 1093660, 76335, '<td valign="top">Good use of high contrast to tell the story.</td>', 'Good use of high contrast to tell the story.', '2013-12-06 11:13:21.000000', NULL, 1),
(7139623, 1093712, 100831, '<td valign="top">I can''t say I''d want this to hang on the wall of MY house... but there''s a spontaneity about it that I really like.</td>', 'I can''t say I''d want this to hang on the wall of MY house... but there''s a spontaneity about it that I really like.', '2013-12-06 12:58:27.000000', NULL, 1),
(7139634, 1092999, 94815, '<td valign="top">Almost Cubist. A truly painterly photograph. Compelling tension between the head and painted silhouette. Nice work. 9</td>', 'Almost Cubist. A truly painterly photograph. Compelling tension between the head and painted silhouette. Nice work. 9', '2013-12-06 14:11:16.000000', NULL, 1),
(7139654, 1093367, 114225, '<td valign="top">These photos always amuse me.</td>', 'These photos always amuse me.', '2013-12-06 16:41:15.000000', NULL, 1),
(7139655, 1093764, 114225, '<td valign="top">I like the reflection and the feel of the water. But the lack of focus on the bird is killing this for me.</td>', 'I like the reflection and the feel of the water. But the lack of focus on the bird is killing this for me.', '2013-12-06 16:42:03.000000', NULL, 1),
(7139657, 1090694, 114225, '<td valign="top">Is that realistic color in the sky?</td>', 'Is that realistic color in the sky?', '2013-12-06 16:42:32.000000', NULL, 1),
(7139658, 1093520, 114225, '<td valign="top">Wow, that is some cool use of color.</td>', 'Wow, that is some cool use of color.', '2013-12-06 16:43:07.000000', NULL, 1),
(7139660, 1093528, 114225, '<td valign="top">Real of fake?<br/> <br/>Either way, I like the light.</td>', 'Real of fake? Either way, I like the light.', '2013-12-06 16:44:33.000000', NULL, 1),
(7139661, 1092177, 114225, '<td valign="top">Nice job making the everyday interesting.</td>', 'Nice job making the everyday interesting.', '2013-12-06 16:44:49.000000', NULL, 1),
(7139662, 1093172, 114225, '<td valign="top">The lines/curves in this image are great.</td>', 'The lines/curves in this image are great.', '2013-12-06 16:45:05.000000', NULL, 1),
(7139663, 1092704, 114225, '<td valign="top">Ha, great portrait.</td>', 'Ha, great portrait.', '2013-12-06 16:45:40.000000', NULL, 1),
(7139664, 1090393, 114225, '<td valign="top">I like the pose and the softness of the image, but I find myself wanting the face to be brighter.</td>', 'I like the pose and the softness of the image, but I find myself wanting the face to be brighter.', '2013-12-06 16:46:14.000000', NULL, 1),
(7139665, 1093555, 114225, '<td valign="top">That''s some cool color.</td>', 'That''s some cool color.', '2013-12-06 16:46:25.000000', NULL, 1),
(7139666, 1092994, 114225, '<td valign="top">Wow, this photo has so much mood, especially for architecture.</td>', 'Wow, this photo has so much mood, especially for architecture.', '2013-12-06 16:46:48.000000', NULL, 1),
(7139667, 1093796, 114225, '<td valign="top">Great perspective choice to make the ordinary interesting.</td>', 'Great perspective choice to make the ordinary interesting.', '2013-12-06 16:47:07.000000', NULL, 1),
(7139670, 1090538, 114225, '<td valign="top">Wow, great view.</td>', 'Wow, great view.', '2013-12-06 17:28:52.000000', NULL, 1),
(7139671, 1093654, 114225, '<td valign="top">Intense.</td>', 'Intense.', '2013-12-06 17:29:00.000000', NULL, 1),
(7139672, 1093607, 114225, '<td valign="top">So eerily serene.</td>', 'So eerily serene.', '2013-12-06 17:29:14.000000', NULL, 1),
(7139673, 1093739, 114225, '<td valign="top">Fantastic lines.</td>', 'Fantastic lines.', '2013-12-06 17:29:20.000000', NULL, 1),
(7139674, 1093706, 114225, '<td valign="top">Too bad the starts are not in focus, that could really make this pop.<br/> <br/>FYI, in advanced editing, you could have taken on photo with the foreground in focus, one photo with the stars in focus, and combined them in post processing to make sure all was in focus.</td>', 'Too bad the starts are not in focus, that could really make this pop. FYI, in advanced editing, you could have taken on photo with the foreground in focus, one photo with the stars in focus, and combined them in post processing to make sure all was in focus.', '2013-12-06 17:30:45.000000', NULL, 1),
(7139676, 1093840, 114225, '<td valign="top">Like a painting.</td>', 'Like a painting.', '2013-12-06 17:33:10.000000', NULL, 1),
(7139678, 1093802, 114225, '<td valign="top">I like where this started, but not where it ended. The post processing, especially on the skin, is way too drastic for me. There are also some weird color issues going on.</td>', 'I like where this started, but not where it ended. The post processing, especially on the skin, is way too drastic for me. There are also some weird color issues going on.', '2013-12-06 17:34:10.000000', NULL, 1),
(7139679, 1090351, 114225, '<td valign="top">Wow, great color to capture the flight.</td>', 'Wow, great color to capture the flight.', '2013-12-06 17:34:24.000000', NULL, 1),
(7139680, 1093728, 114225, '<td valign="top">The curves caused by the lens are actually interesting here.</td>', 'The curves caused by the lens are actually interesting here.', '2013-12-06 17:35:08.000000', NULL, 1),
(7139681, 1093446, 114225, '<td valign="top">This is more interesting than it seems at first glance.</td>', 'This is more interesting than it seems at first glance.', '2013-12-06 17:35:40.000000', NULL, 1),
(7139683, 1093709, 60047, '<td valign="top">An interesting perspective on the inner city.</td>', 'An interesting perspective on the inner city.', '2013-12-06 18:07:54.000000', NULL, 1),
(7139685, 1093562, 60047, '<td valign="top">I like the textures in this shot.</td>', 'I like the textures in this shot.', '2013-12-06 18:08:38.000000', NULL, 1),
(7139686, 1093637, 60047, '<td valign="top">I like what you''ve done with burning the clouds. It contrasts well with the orange leaves. You may want to pull back on the tool''s burn strength percentage, though, and make several lighter passes...there are some areas where you can see the circular burn tool pattern.</td>', 'I like what you''ve done with burning the clouds. It contrasts well with the orange leaves. You may want to pull back on the tool''s burn strength percentage, though, and make several lighter passes...there are some areas where you can see the circular burn tool pattern.', '2013-12-06 18:12:27.000000', NULL, 1),
(7139687, 1090499, 60047, '<td valign="top">I find myself really wanting to see more of that bridge in the BG.Nice Fall scene.</td>', 'I find myself really wanting to see more of that bridge in the BG.Nice Fall scene.', '2013-12-06 18:13:21.000000', NULL, 1),
(7139689, 1093802, 60047, '<td valign="top">Had to spend a lot of time staring at this one. There''s a wonderful element of semi-creepy "Is that a doll or a real person?" aspect to this shot. Pretty cool.</td>', 'Had to spend a lot of time staring at this one. There''s a wonderful element of semi-creepy "Is that a doll or a real person?" aspect to this shot. Pretty cool.', '2013-12-06 18:14:38.000000', NULL, 1),
(7139690, 1093731, 60047, '<td valign="top">Love the blue tones.</td>', 'Love the blue tones.', '2013-12-06 18:15:05.000000', NULL, 1),
(7139691, 1090351, 60047, '<td valign="top">Really awesome contrast of colors between the blue birds and mauve sky. Nioce capture.</td>', 'Really awesome contrast of colors between the blue birds and mauve sky. Nioce capture.', '2013-12-06 18:16:01.000000', NULL, 1),
(7139692, 1093759, 60047, '<td valign="top">Wow. That sky is the equivalent of a visual sweet-tart! Cool that you got the tractor in the shot as well.</td>', 'Wow. That sky is the equivalent of a visual sweet-tart! Cool that you got the tractor in the shot as well.', '2013-12-06 18:17:04.000000', NULL, 1),
(7139693, 1093717, 60047, '<td valign="top">Love the Red and deep Greens. Nice composition choice. There''s a noticeable amount of noise in the greens and darker tones.</td>', 'Love the Red and deep Greens. Nice composition choice. There''s a noticeable amount of noise in the greens and darker tones.', '2013-12-06 18:19:00.000000', NULL, 1),
(7139695, 1093347, 60047, '<td valign="top">Great textures in her skin. Cool expression.</td>', 'Great textures in her skin. Cool expression.', '2013-12-06 18:19:36.000000', NULL, 1),
(7139700, 1092918, 60047, '<td valign="top">I find her long tail kinda cool. This appears to be taken from the more common snap-shot POV of the photographer standing and looking down. I would encourage you to maybe try different POV like kneeling or even from ground level.</td>', 'I find her long tail kinda cool. This appears to be taken from the more common snap-shot POV of the photographer standing and looking down. I would encourage you to maybe try different POV like kneeling or even from ground level.', '2013-12-06 18:22:12.000000', NULL, 1),
(7139701, 1093661, 60047, '<td valign="top">A cool capture. It''s always neat to see the details of a bird in flight.</td>', 'A cool capture. It''s always neat to see the details of a bird in flight.', '2013-12-06 18:23:12.000000', NULL, 1),
(7139703, 1091726, 60047, '<td valign="top">Nice pan effect.</td>', 'Nice pan effect.', '2013-12-06 18:23:46.000000', NULL, 1),
(7139705, 1090167, 60047, '<td valign="top">Interesting choice of title. Great detail on the top of the web - too bad you couldn''t tighten up the aperture and get enough DOF to fit the whole web in focus.</td>', 'Interesting choice of title. Great detail on the top of the web - too bad you couldn''t tighten up the aperture and get enough DOF to fit the whole web in focus.', '2013-12-06 18:25:16.000000', NULL, 1),
(7139724, 1093528, 150277, '<td valign="top">Awesome.</td>', 'Awesome.', '2013-12-06 19:31:18.000000', NULL, 1),
