(7139897, 1093367, 60047, '<td valign="top">I never get tired of seeing this iconic shot! What a mind-bender. You''ve really captured it well.</td>', 'I never get tired of seeing this iconic shot! What a mind-bender. You''ve really captured it well.', '2013-12-07 13:31:28.000000', NULL, 1),
(7139898, 1093706, 60047, '<td valign="top">Though the stars in this photo are the understood stars of the show in a photo like this, I really like the soft greys of the water contrasted with the clear silhouettes of rocks and trees.</td>', 'Though the stars in this photo are the understood stars of the show in a photo like this, I really like the soft greys of the water contrasted with the clear silhouettes of rocks and trees.', '2013-12-07 13:36:37.000000', NULL, 1),
(7139899, 1093568, 60047, '<td valign="top">What a great capture!</td>', 'What a great capture!', '2013-12-07 13:36:59.000000', NULL, 1),
(7139900, 1092290, 60047, '<td valign="top">Nice contrast of blues and yellows.</td>', 'Nice contrast of blues and yellows.', '2013-12-07 13:37:33.000000', NULL, 1),
(7139901, 1093840, 60047, '<td valign="top">I love the reds of the sumac leaves in the Fall. The color splotches and texture differences in this shot are great.</td>', 'I love the reds of the sumac leaves in the Fall. The color splotches and texture differences in this shot are great.', '2013-12-07 13:39:28.000000', NULL, 1),
(7139902, 1093707, 60047, '<td valign="top">You''ve achieved a color richness of the blues and oranges that is right on the mark. Not too soft, but not too overdone. The addition of the reeds in the FG really helps with the composition of this shot.</td>', 'You''ve achieved a color richness of the blues and oranges that is right on the mark. Not too soft, but not too overdone. The addition of the reeds in the FG really helps with the composition of this shot.', '2013-12-07 13:41:02.000000', NULL, 1),
(7139903, 1091734, 60047, '<td valign="top">It''s hard for me not to fall in love with a shot of a Cardinal in the snow! If only those blurred areas weren''t there, this would be perfect for me.</td>', 'It''s hard for me not to fall in love with a shot of a Cardinal in the snow! If only those blurred areas weren''t there, this would be perfect for me.', '2013-12-07 13:42:12.000000', NULL, 1),
(7139904, 1093628, 60047, '<td valign="top">I like the composition of this one - wide open landscapes can be tough. I''m really curious about the choice of B&amp;W.</td>', 'I like the composition of this one - wide open landscapes can be tough. I''m really curious about the choice of B&W.', '2013-12-07 13:43:17.000000', NULL, 1),
(7139906, 1093739, 60047, '<td valign="top">A great shot of an unfamiliar landscape (flats with the tide out).</td>', 'A great shot of an unfamiliar landscape (flats with the tide out).', '2013-12-07 13:44:24.000000', NULL, 1),
(7139907, 1093870, 60047, '<td valign="top">I love the locale. My personal preference would be to back off the saturation just a tad. The inclusion of the town in the BG really adds to this shot''s appeal.</td>', 'I love the locale. My personal preference would be to back off the saturation just a tad. The inclusion of the town in the BG really adds to this shot''s appeal.', '2013-12-07 13:45:36.000000', NULL, 1),
(7139908, 1093520, 60047, '<td valign="top">Great composition and POV. Nice to see that this appears to not be a contrived shot. Great color contrasts against the greys.</td>', 'Great composition and POV. Nice to see that this appears to not be a contrived shot. Great color contrasts against the greys.', '2013-12-07 13:46:46.000000', NULL, 1),
