(7140010, 1093567, 102278, '<td valign="top">Massive, hulking weight. A marvellous photograph. 10.</td>', 'Massive, hulking weight. A marvellous photograph. 10.', '2013-12-07 19:15:01.000000', NULL, 1),
(7140011, 1093344, 102278, '<td valign="top">I like this very much. Breaking Glass. Very 70''s. 9</td>', 'I like this very much. Breaking Glass. Very 70''s. 9', '2013-12-07 19:15:35.000000', NULL, 1),
