(7140016, 1090538, 102278, '<td valign="top">Very interesting shot! 8.</td>', 'Very interesting shot! 8.', '2013-12-07 19:20:13.000000', NULL, 1),
(7140021, 1093709, 76335, '<td valign="top">What a collage!</td>', 'What a collage!', '2013-12-07 19:35:03.000000', NULL, 1),
(7140022, 1093818, 76335, '<td valign="top">Nice vibe.</td>', 'Nice vibe.', '2013-12-07 19:35:13.000000', NULL, 1),
(7140023, 1093549, 18367, '<td valign="top">I am not a betting man, but if I were I would wager that this photo was taken at Fraser Island in Australia.  Mind you, the ruts don''t look deep enough... I truly enjoyed the bus ride and would recommend it to anyone..<br/> <br/>Best of luck with the challenge.</td>', 'I am not a betting man, but if I were I would wager that this photo was taken at Fraser Island in Australia.  Mind you, the ruts don''t look deep enough... I truly enjoyed the bus ride and would recommend it to anyone.. Best of luck with the challenge.', '2013-12-07 19:35:14.000000', NULL, 1),
(7140024, 1091738, 76335, '<td valign="top">Fantastic find.</td>', 'Fantastic find.', '2013-12-07 19:36:02.000000', NULL, 1),
(7140025, 1093397, 76335, '<td valign="top">Nice, though I kind of wish for a lighter background to give more shape to the hair.</td>', 'Nice, though I kind of wish for a lighter background to give more shape to the hair.', '2013-12-07 19:37:44.000000', NULL, 1),
(7140026, 1093621, 76335, '<td valign="top">Radiant.</td>', 'Radiant.', '2013-12-07 19:37:49.000000', NULL, 1),
(7140030, 1091831, 60047, '<td valign="top">A really different perspective on Autumn foliage!</td>', 'A really different perspective on Autumn foliage!', '2013-12-07 19:46:04.000000', NULL, 1),
(7140031, 1093719, 60047, '<td valign="top">Captivating shot when considering the title...</td>', 'Captivating shot when considering the title...', '2013-12-07 19:46:33.000000', NULL, 1),
(7140032, 1093621, 60047, '<td valign="top">Striking orange.</td>', 'Striking orange.', '2013-12-07 19:47:01.000000', NULL, 1),
(7140033, 1093820, 60047, '<td valign="top">Great detail. Focus is right where it needs to be. I would have preferred a bit of a deeper DOF just to get more feather detail.</td>', 'Great detail. Focus is right where it needs to be. I would have preferred a bit of a deeper DOF just to get more feather detail.', '2013-12-07 19:48:19.000000', NULL, 1),
(7140034, 1093375, 60047, '<td valign="top">This could easily be a product shot in any magazine. Nice work that could easily go commercial.</td>', 'This could easily be a product shot in any magazine. Nice work that could easily go commercial.', '2013-12-07 19:48:54.000000', NULL, 1),
(7140035, 1093725, 60047, '<td valign="top">Nice color palette.</td>', 'Nice color palette.', '2013-12-07 19:53:53.000000', NULL, 1),
(7140036, 1093587, 60047, '<td valign="top">I have this feeling that I''m missing something...</td>', 'I have this feeling that I''m missing something...', '2013-12-07 19:54:18.000000', NULL, 1),
(7140038, 1093850, 60047, '<td valign="top">A fascinating expression.</td>', 'A fascinating expression.', '2013-12-07 19:54:48.000000', NULL, 1),
(7140039, 1093701, 60047, '<td valign="top">A pretty cool composition. Pretty impressive light management considering the brights vs the darks in this shot. Nice textures illuminated in the asphalt.</td>', 'A pretty cool composition. Pretty impressive light management considering the brights vs the darks in this shot. Nice textures illuminated in the asphalt.', '2013-12-07 19:56:13.000000', NULL, 1),
(7140040, 1093845, 60047, '<td valign="top">Wow. Really awesome capture.</td>', 'Wow. Really awesome capture.', '2013-12-07 19:56:43.000000', NULL, 1),
(7140041, 1092916, 60047, '<td valign="top">This is really quite a cool shot. Great color contrast between the whites and the oranges.</td>', 'This is really quite a cool shot. Great color contrast between the whites and the oranges.', '2013-12-07 19:58:06.000000', NULL, 1),
(7140042, 1093753, 60047, '<td valign="top">I keep going back to the mime''s face and wonder about it''s creepiness!</td>', 'I keep going back to the mime''s face and wonder about it''s creepiness!', '2013-12-07 19:58:45.000000', NULL, 1),
(7140043, 1093873, 60047, '<td valign="top">Love the choice of soft focus effect.</td>', 'Love the choice of soft focus effect.', '2013-12-07 19:59:07.000000', NULL, 1),
(7140044, 1093555, 60047, '<td valign="top">What a fascinating sky blue color in the water.</td>', 'What a fascinating sky blue color in the water.', '2013-12-07 19:59:33.000000', NULL, 1),
(7140046, 1093535, 60047, '<td valign="top">An atypical choice - shooting directly into the sun. You handle that well, here.</td>', 'An atypical choice - shooting directly into the sun. You handle that well, here.', '2013-12-07 20:01:00.000000', NULL, 1),
(7140047, 1093833, 60047, '<td valign="top">Love the lines and use of reflections in this composition.</td>', 'Love the lines and use of reflections in this composition.', '2013-12-07 20:01:50.000000', NULL, 1),
(7140048, 1093725, 12611, '<td valign="top">A haunting image.</td>', 'A haunting image.', '2013-12-07 20:01:52.000000', NULL, 1),
(7140050, 1093612, 60047, '<td valign="top">This portrait really tells a great story. Nice work.</td>', 'This portrait really tells a great story. Nice work.', '2013-12-07 20:02:27.000000', NULL, 1),
(7140051, 1093478, 60047, '<td valign="top">A clever way to shoot directly into the sun.</td>', 'A clever way to shoot directly into the sun.', '2013-12-07 20:03:14.000000', NULL, 1),
(7140052, 1093153, 60047, '<td valign="top">Trying to understand the crystalline structure in the upper left corner.</td>', 'Trying to understand the crystalline structure in the upper left corner.', '2013-12-07 20:04:57.000000', NULL, 1),
(7140053, 1093716, 60047, '<td valign="top">Each of the three people have great expressions on their faces.</td>', 'Each of the three people have great expressions on their faces.', '2013-12-07 20:07:13.000000', NULL, 1),
(7140054, 1093859, 60047, '<td valign="top">Each of the three sections of this photo are striking - the colored foliage in the FG, the falls, and the striking sky. Nice work.</td>', 'Each of the three sections of this photo are striking - the colored foliage in the FG, the falls, and the striking sky. Nice work.', '2013-12-07 20:08:37.000000', NULL, 1),
(7140055, 1093855, 60047, '<td valign="top">Vertigo!</td>', 'Vertigo!', '2013-12-07 20:09:00.000000', NULL, 1),
(7140056, 1093646, 60047, '<td valign="top">Now that''s a cool take on a great sunset. Great silhouettes!</td>', 'Now that''s a cool take on a great sunset. Great silhouettes!', '2013-12-07 20:09:34.000000', NULL, 1),
(7140058, 1093349, 60047, '<td valign="top">A nice version of an iconic subject. Cool effect.</td>', 'A nice version of an iconic subject. Cool effect.', '2013-12-07 20:10:02.000000', NULL, 1),
(7140059, 1093832, 60047, '<td valign="top">Love the geometric patterns. Fascinating - not sure if this is a macro B&amp;W shot of a crystalline structure or an infrared shot of foliage. In any case it is captivating and cool to look at.</td>', 'Love the geometric patterns. Fascinating - not sure if this is a macro B&W shot of a crystalline structure or an infrared shot of foliage. In any case it is captivating and cool to look at.', '2013-12-07 20:12:18.000000', NULL, 1),
(7140060, 1093055, 60047, '<td valign="top">Great time lapse shot. I love the eddy on the right.</td>', 'Great time lapse shot. I love the eddy on the right.', '2013-12-07 20:12:48.000000', NULL, 1),
(7140061, 1093615, 60047, '<td valign="top">I really like the heavy blues in this shot.</td>', 'I really like the heavy blues in this shot.', '2013-12-07 20:13:20.000000', NULL, 1),
(7140062, 1093763, 60047, '<td valign="top">A great unusual POV on a well known subject. Nice work.</td>', 'A great unusual POV on a well known subject. Nice work.', '2013-12-07 20:13:58.000000', NULL, 1),
(7140063, 1093857, 60047, '<td valign="top">Nice to capture this action at the point of impact.</td>', 'Nice to capture this action at the point of impact.', '2013-12-07 20:14:27.000000', NULL, 1),
(7140064, 1093858, 60047, '<td valign="top">We see a lot of flower shots on DPC. This is a pleasing one to look at. Good work.</td>', 'We see a lot of flower shots on DPC. This is a pleasing one to look at. Good work.', '2013-12-07 20:15:05.000000', NULL, 1),
(7140065, 1093871, 60047, '<td valign="top">Nice job on the studio lighting.</td>', 'Nice job on the studio lighting.', '2013-12-07 20:16:36.000000', NULL, 1),
(7140066, 1093760, 60047, '<td valign="top">I like this shot. I''m trying to understand the sense of haziness I am perceiving.</td>', 'I like this shot. I''m trying to understand the sense of haziness I am perceiving.', '2013-12-07 20:17:30.000000', NULL, 1),
(7140067, 1089918, 60047, '<td valign="top">Fascinating subject choice. Great colors.</td>', 'Fascinating subject choice. Great colors.', '2013-12-07 20:18:17.000000', NULL, 1),
(7140069, 1093519, 60047, '<td valign="top">I love shots of old and decaying buildings. There must be a reason why you chose to cut off the right edge.</td>', 'I love shots of old and decaying buildings. There must be a reason why you chose to cut off the right edge.', '2013-12-07 20:20:43.000000', NULL, 1),
(7140070, 1093504, 60047, '<td valign="top">Nice lighting to go with this one. Impressed with the deep blue color in his eyes.</td>', 'Nice lighting to go with this one. Impressed with the deep blue color in his eyes.', '2013-12-07 20:22:01.000000', NULL, 1),
(7140071, 1093787, 60047, '<td valign="top">A "classic" look to this shot. I really like the combination of the fog, the red plaid, and the white dog.</td>', 'A "classic" look to this shot. I really like the combination of the fog, the red plaid, and the white dog.', '2013-12-07 20:23:04.000000', NULL, 1),
(7140072, 1093874, 60047, '<td valign="top">A very good shot of an iconic subject.</td>', 'A very good shot of an iconic subject.', '2013-12-07 20:23:45.000000', NULL, 1),
